#include <vector>
using namespace std;

class Solution {
public:
    int countResiduePrefixes(vector<int>& nums, int k) {
        long long pref_sum = 0;
        int count = 0;
        for (int x : nums) {
            pref_sum = (pref_sum + x) % k;
            if (pref_sum == (x % k)) count++;
        }
        return count;
    }
};

